/**
 * Type definitions matching the API specification
 */
export interface ColumnSchema {
    name: string;
    prompt: string;
    primaryKey?: boolean;
    unique?: boolean;
    autoIncrement?: boolean;
    nullable?: boolean;
    reanalyzeExisting?: boolean;
    type?: "text" | "number" | "date" | "boolean" | "foreign_key";
    referencedTable?: string;
    referencedColumn?: string;
    parentTable?: string;
}
export interface InlineArraySchema {
    name: string;
    columns: ColumnSchema[];
}
export interface ChildTableSchema {
    name: string;
    columns: ColumnSchema[];
}
export interface TableSchema {
    name: string;
    columns: ColumnSchema[];
    inlineArrays?: InlineArraySchema[];
    childTables?: ChildTableSchema[];
}
export interface Table {
    id: string;
    name: string;
    slug: string;
    columns: ColumnSchema[];
    projects_id: number;
    user_id: string;
    last_extracted_at?: string | null;
    created_at: string | null;
    updated_at: string | null;
}
export type DocumentStatus = "queued" | "processing" | "completed" | "failed" | "error" | "classifying" | "classified" | "unclassified";
export interface Document {
    id: number;
    file_id: string;
    upload_id: string;
    name: string;
    status: DocumentStatus;
    file_size?: number;
    page_count?: number;
    is_duplicate: boolean;
    duplicate_count: number;
    mistral_id?: string;
    user_id: string;
    project_id: number;
    table_id: string | null;
    processed_at?: string | null;
    created_at: string | null;
    updated_at: string | null;
}
export interface DocumentListItem {
    id: number;
    document_record_id: string;
    name: string;
    status: DocumentStatus;
    file_size?: number;
    page_count?: number;
    table_id: string | null;
    tableName?: string;
    tableSlug?: string | null;
    routingStatus?: string | null;
    routingConfidence?: number | null;
    routingReasoning?: string | null;
    routingError?: string | null;
    routingRuleId?: string | null;
    routingRuleName?: string | null;
    routingSuggestedTableId?: string | null;
    routingThreshold?: number | null;
    created_at: string | null;
}
export type JobStatus = "queued" | "in_progress" | "completed" | "failed" | "waiting";
export interface JobBatch {
    id: number;
    batch_id: string;
    workflow_instance_id: string;
    status: string;
    created_at: string | null;
    updated_at: string | null;
}
export interface Job {
    id: number;
    user_id?: string;
    projects_id: number;
    table_id: string;
    workflow_type?: string | null;
    job_status: JobStatus;
    created_at: string | null;
    updated_at: string | null;
    batches?: JobBatch[];
}
export type ExtractionStatus = "success" | "failed";
export interface ExtractionAttempt {
    id: number;
    document_id: number;
    job_id?: number;
    workflow_instance_id: string;
    workflow_type: "ocr" | "reanalyze";
    status: ExtractionStatus;
    extracted_data?: Record<string, unknown>;
    error_message?: string;
    error_details?: string;
    attempt_number: number;
    started_at: string | null;
    completed_at: string | null;
    processing_duration_ms?: number;
    table_id: string;
    tableName?: string;
    created_at: string | null;
}
export interface FailedExtractionAttempt {
    attempt: {
        id: number;
        workflow_instance_id: string;
        workflow_type: "ocr" | "reanalyze";
        status: ExtractionStatus;
        attempt_number: number;
        started_at: string | null;
        completed_at: string | null;
        processing_duration_ms?: number;
        created_at: string | null;
    };
    table: {
        id: string;
        name: string;
    };
    document: {
        id: number;
        name: string;
        file_id: string;
        status: DocumentStatus;
        file_size?: number;
        page_count?: number;
        created_at: string | null;
    };
    error?: {
        code: string | null;
        message: string | null;
        details?: string | null;
        timestamp: string | null;
    };
}
export interface CreateTableRequest extends TableSchema {
}
export interface UpdateTableRequest {
    name?: string;
    columns?: ColumnSchema[];
}
export interface UploadMetadata {
    /** Omit to send the document through the project's automatic routing rules. */
    tableSlug?: string;
    filename: string;
    /** @deprecated Canonical file IDs are generated by the Upload Worker. */
    file_id?: string;
    user_id?: string;
    name?: string;
    type?: string;
    file_size?: number;
}
export interface UploadResult {
    uploadId: string;
    location?: string;
    status: "uploaded";
    fileId: string;
}
export interface DocumentFilters {
    status?: DocumentStatus;
    table_id?: string;
}
export interface DeleteDocumentsRequest {
    documentRecordIds: string[];
    documentsTableName: string;
    deleteDocuments?: boolean;
}
export interface DeleteDocumentResponse {
    document_id: number;
    workflow_id: string;
    status: string;
}
export interface RouteDocumentResponse {
    success: true;
    jobId: number;
    workflowId: string;
}
export interface CreateJobRequest {
    tableSlug: string;
    documentKeys: string[];
}
export type ExtractJobConfig = CreateJobRequest;
export interface MutationOptions {
    /** Reuse for a retry of the same operation and body, never for different input. */
    idempotencyKey?: string;
}
export interface ReanalyzeJobConfig {
    documentRecordIds: string[];
    table: string;
}
export interface PollOptions {
    interval?: number;
    timeout?: number;
    onProgress?: (status: string) => void;
}
export interface ExtractionResult {
    job: Job;
    extractedData?: Record<string, unknown>;
    attempts?: ExtractionAttempt[];
}
export interface Agent {
    id: string;
    user_id: string;
    name: string;
    description?: string | null;
    status: "active" | "disabled";
    createdAt: string | null;
    updatedAt: string | null;
}
export interface AgentApiKey {
    id: string;
    key_prefix: string;
    label?: string | null;
    revoked_at?: string | null;
    last_used_at?: string | null;
    createdAt: string | null;
}
export type RouteScope = "*" | "agents:manage" | "projects:read" | "projects:write" | "projects:delete" | "tables:read" | "tables:write" | "tables:delete" | "rows:read" | "rows:write" | "rows:delete" | "documents:read" | "documents:write" | "documents:delete" | "jobs:read" | "jobs:write" | "webhooks:manage" | "uploads:read" | "uploads:write";
export interface AgentDetails extends Agent {
    route_permissions: Array<{
        id: string;
        agent_id: string;
        scope: RouteScope;
        route_pattern?: string | null;
        method?: string | null;
    }>;
    project_permissions: Array<{
        id: string;
        agent_id: string;
        project_id: number;
    }>;
    keys: AgentApiKey[];
}
export interface CreateAgentRequest {
    name: string;
    description?: string;
}
export interface UpdateAgentRequest {
    name?: string;
    description?: string | null;
    status?: "active" | "disabled";
}
export interface CreateAgentKeyRequest {
    label?: string;
}
export interface CreateAgentKeyResponse extends AgentApiKey {
    api_key: string;
}
export interface RowRecord {
    [key: string]: unknown;
}
export interface Row extends RowRecord {
    row_id: string;
    document_record_id?: string;
}
export interface InsertRowRequest {
    table_id: string;
    document_record_id?: string;
    values: RowRecord;
}
export type CreateRowRequest = InsertRowRequest;
export interface QueryRowsRequest {
    table_id: string;
    filters?: Array<{
        column: string;
        op: "eq" | "ne" | "gt" | "gte" | "lt" | "lte" | "like" | "in";
        value: unknown;
    }>;
    orderBy?: {
        column: string;
        direction?: "asc" | "desc";
    };
    page?: number;
    pageSize?: number;
}
export interface QueryRowsResponse {
    results: Row[];
    total: number;
    page: number;
    pageSize: number;
    pageCount: number;
}
export interface CreateRowResponse {
    row_id: string;
    document_record_id: string;
    row: Row | null;
}
export interface UpdateRowResponse {
    row_id: string;
    row: Row;
}
export interface WebhookEndpoint {
    id: string;
    user_id: string;
    project_id?: number | null;
    url: string;
    description?: string | null;
    status: "active" | "disabled";
    events: string[];
    createdAt: string | null;
    updatedAt: string | null;
}
export interface CreateWebhookEndpointRequest {
    url: string;
    description?: string;
    events: string[];
    project_id?: number;
}
export interface CreateWebhookEndpointResponse extends WebhookEndpoint {
    signing_secret: string;
}
export interface UpdateWebhookEndpointRequest {
    url?: string;
    description?: string | null;
    events?: string[];
    status?: "active" | "disabled";
}
export interface WebhookDelivery {
    id: string;
    endpoint_id: string;
    event_id: string;
    event_type: string;
    attempt: number;
    status: "pending" | "retrying" | "delivered" | "failed";
    request_body?: string | null;
    signature?: string | null;
    response_status?: number | null;
    response_body?: string | null;
    delivered_at?: string | null;
    next_attempt_at?: string | null;
    createdAt: string | null;
}
/** A rule used to route newly uploaded documents to a destination table. */
export interface RoutingRule {
    id: string;
    name: string;
    prompt: string;
    confidenceThreshold: number;
    enabled: boolean;
    tableId: string;
    tableName: string;
    tableSlug: string;
    createdAt: string | null;
    updatedAt: string | null;
}
export interface CreateRoutingRuleRequest {
    name: string;
    prompt: string;
    confidenceThreshold?: number;
    tableId: string;
    enabled?: boolean;
}
export type UpdateRoutingRuleRequest = Partial<CreateRoutingRuleRequest>;
export interface SplitterPageSpan {
    /** One-indexed inclusive page number. */
    start_page: number;
    /** One-indexed inclusive page number. */
    end_page: number;
}
export interface SplitterSection {
    section_key: string;
    name: string;
    description?: string;
    destination_table_id: string;
    page_spans: SplitterPageSpan[];
}
export interface PageRangeSplitterConfig {
    mode?: "page_range";
    overlap_policy?: "exclusive" | "allowed";
    unassigned_policy?: "review" | "ignore" | "fallback";
    fallback_section_key?: string;
    max_segments?: number;
    sections: SplitterSection[];
}
export interface Splitter {
    id: string;
    name: string;
    description: string | null;
    mode: "page_range";
    status: "draft" | "published" | "archived";
    draft_revision: number;
    latest_version: number;
    config: Required<Pick<PageRangeSplitterConfig, "mode" | "overlap_policy" | "unassigned_policy" | "max_segments">> & Pick<PageRangeSplitterConfig, "fallback_section_key" | "sections">;
    created_at: string | null;
    updated_at: string | null;
}
export interface SplitterVersionSummary {
    id: string;
    version: number;
    revision_hash: string;
    published_at: string | null;
}
export interface SplitterDetail extends Splitter {
    versions: SplitterVersionSummary[];
}
export interface CreateSplitterRequest {
    name: string;
    description?: string;
    config: PageRangeSplitterConfig;
}
export interface UpdateSplitterRequest {
    name?: string;
    description?: string | null;
    config?: PageRangeSplitterConfig;
    expected_draft_revision: number;
}
export interface PublishSplitterResult {
    splitter_id: string;
    version_id: string;
    version: number;
    revision_hash: string;
    published_at: string | null;
    reused: boolean;
}
export interface SplitterPreviewSegment {
    segment_key: string;
    section_key: string;
    section_name: string;
    destination_table_id: string;
    page_spans: SplitterPageSpan[];
    page_count: number;
    ordinal: number;
    review_required: boolean;
}
export interface SplitterPreview {
    splitter_id: string;
    version: number | null;
    draft_revision: number | null;
    page_count: number;
    segments: SplitterPreviewSegment[];
    unassigned_page_spans: SplitterPageSpan[];
    overlaps: Array<{
        page: number;
        section_keys: string[];
    }>;
    review_required: boolean;
    unique_assigned_page_count: number;
    downstream_page_count: number;
}
export interface SplitterRunSegment {
    id: string;
    segment_key: string;
    ordinal: number;
    page_spans: SplitterPageSpan[];
    page_count: number;
    review_status: "not_required" | "pending" | "approved" | "rejected";
    destination_table_id: string;
}
export interface SplitterRun {
    processing_run_id: string;
    split_run_id: string;
    splitter_id: string;
    version_id: string;
    version: number;
    status: "succeeded" | "waiting_for_review";
    segment_count: number;
    review_count: number;
    segments: SplitterRunSegment[];
}
export type SqlParameter = string | number | boolean;
/** The portable shape returned by Drizzle's `toSQL()` method. */
export interface DrizzleSqlQuery {
    toSQL(): {
        sql: string;
        params: readonly unknown[];
    };
}
/** The portable shape returned by Kysely's `compile()` method. */
export interface KyselyCompiledSqlQuery {
    sql: string;
    parameters: readonly unknown[];
}
export interface CompiledSqlQuery {
    sql: string;
    params?: readonly unknown[];
}
export type SqlQueryInput = string | CompiledSqlQuery | KyselyCompiledSqlQuery | DrizzleSqlQuery;
export interface SqlQueryOptions {
    maxRows?: number;
}
export interface SqlQueryResult<Row extends RowRecord = RowRecord> {
    columns: string[];
    rows: Row[];
    rowCount: number;
    maxRows: number;
    truncated: boolean;
    durationMs: number;
    rowsRead: number;
}
export interface McpCallToolResult {
    content: Array<{
        type: string;
        text?: string;
    }>;
    isError?: boolean;
}
